	set_git "$ROTATION_DB"
	now="$(date +%s)"
	tmp="$(mktemp "$ROTATION_DB.XXXXXX")" || return
	awk -F '\t' -v old="$old" -v new="$new" -v now="$now" '
		BEGIN { OFS = "\t" }
